changeSet.sql:
ALTER TABLE modeling_dimension_definition
    ADD CONSTRAINT ck_dimension_definition_scope
    CHECK (
        (scope_type = 'DOMAIN' AND data_mart_id IS NULL)
        OR (scope_type = 'DATA_MART' AND data_mart_id IS NOT NULL)
    );
ALTER TABLE modeling_dimension_definition_revision
    ADD CONSTRAINT ck_dimension_definition_revision_scope
    CHECK (
        ((scope_type = 'DOMAIN' AND data_mart_id IS NULL)
            OR (scope_type = 'DATA_MART' AND data_mart_id IS NOT NULL))
        AND jsonb_typeof(attributes_json) = 'array'
    );
ALTER TABLE modeling_dimension_definition
    ADD CONSTRAINT ck_dimension_definition_attributes
    CHECK (jsonb_typeof(attributes_json) = 'array');
CREATE INDEX idx_dimension_definition_data_mart
    ON modeling_dimension_definition (tenant_id, data_mart_id, status, name)
    WHERE data_mart_id IS NOT NULL;
CREATE INDEX idx_dimension_definition_revision_data_mart
    ON modeling_dimension_definition_revision (tenant_id, data_mart_id, revision DESC)
    WHERE data_mart_id IS NOT NULL;

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_DIMENSION_SCOPE_ATTRIBUTES_FORWARD_ONLY: Recovery requires a new forward changeset';
END $$;
